colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
for ir,r in enumerate(starts):
 for ic,c in enumerate(starts):
  for dr in range(5):
   for dc in range(5):
    rr,cc=r+dr,c+dc
    if rr<30 and cc<30 and (dr in (0,4) or dc in (0,4)):
     out[rr][cc]=4
  if ir<4 and ic<4:
   for dr in range(1,4):
    for dc in range(1,4): out[r+dr][c+dc]=colors[ir][ic]
